node -e '
const s=require("fs").readFileSync("alquimia-reactiva.html","utf8");
const txt=s.match(/RECIPES_TXT = `([\s\S]*?)`;/)[1];
const base=["Código","Café","Idea","Bug"];const seen=new Map();const recs=[];
for(let l of txt.split("\n")){l=l.trim();if(!l)continue;const m=l.match(/^(.+?) \+ (.+?) = (\S+) (.+)$/);if(!m){console.log("BAD",l);continue;}
const k=[m[1],m[2]].sort().join("|");if(seen.has(k))console.log("DUP",k,seen.get(k),m[4]);seen.set(k,m[4]);recs.push([m[1],m[2],m[4]]);}
const known=new Set(base);let ch=true;while(ch){ch=false;for(const[a,b,r]of recs)if(known.has(a)&&known.has(b)&&!known.has(r)){known.add(r);ch=true;}}
const all=new Set([...base,...recs.map(x=>x[2])]);
console.log("total",all.size,"alcanzables",known.size);
for(const r of recs){for(const x of[r[0],r[1]])if(!all.has(x))console.log("INGREDIENTE INEXISTENTE",x);}
for(const x of all)if(!known.has(x))console.log("INALCANZABLE",x);
'
# también comprueba sintaxis del script
node -e 'const s=require("fs").readFileSync("alquimia-reactiva.html","utf8");new Function(s.match(/<script>([\s\S]*)<\/script>/)[1]);console.log("JS OK")'

